# 下游任务头（直接复用 Generic 实现）
# ══════════════════════════════════════════════════════════════════════════════

class Qwen2ForSequenceClassification(GenericForSequenceClassification, Qwen2PreTrainedModel):
    """
    序列分类模型（如情感分析、意图识别）。
    在 [CLS] 位置（通常是最后一个非 padding token）的 hidden_state 上接分类头。
    完全复用 GenericForSequenceClassification 的 forward 逻辑，无需额外实现。
    """
    pass


class Qwen2ForTokenClassification(GenericForTokenClassification, Qwen2PreTrainedModel):
    """
    Token 级别分类模型（如命名实体识别 NER）。
    对每个 token 的 hidden_state 独立做分类，输出 [batch, seq, num_labels]。
    """
    pass


class Qwen2ForQuestionAnswering(GenericForQuestionAnswering, Qwen2PreTrainedModel):
    """
    抽取式问答模型（如 SQuAD）。
    预测答案在原文中的起始和结束位置（start_logits / end_logits）。
    base_model_prefix 设为 "transformer" 是为了兼容部分旧版 checkpoint 的权重键名。
    """
    base_model_prefix = "transformer"  # 历史兼容：旧版本用 "transformer" 而非 "model"


